claim=dict(id='C-verify-current-authority',kind='obligation',concern='consensus_safety',description='In a fixed cluster configuration, a VerifyLeader invocation on a former leader must not return success when, before that invocation, a different voter quorum has elected a higher-term leader and that leader has committed a command, while the former leader remains isolated from that quorum. Responses from nonvoters cannot make the former leader current again.',source_ids=['S-client','S-config','S-membership-api','S-vote','S-election','S-timer-contract'],scope=dict(description='Live non-Byzantine Raft peers using a stable mixed voter/nonvoter configuration, valid server-local timer configurations and a network partition. The higher-term election and completed command precede the VerifyLeader invocation. No membership mutation, manual restore or storage failure overlaps that interval.',assumptions=['Transport returns only actual peer responses or delivery errors; no forged replies.','A majority of configured voters establishes the competing leader and its new command.','Each server satisfies Config validation; timer values may differ across servers, as the captured Config API specifies per-server settings and no cross-server equality rule.'],excluded=['Claiming that any missing response is a deadline violation.','Guaranteeing that the current leader FSM has applied every committed entry without a caller barrier.','Arbitrary direct handler calls or invented preloaded election history.','Byzantine peers, reused server identities, and caller-forced history replacement.']),pending=[],grounding=dict(source_ids=['S-verify','S-verify-vote','S-loop','S-lease','S-repl-start','S-heartbeat','S-inmem-routing','S-config-validation'],expectation_ids=['S-client','S-config','S-membership-api','S-timer-contract'],binding_ids=['BD-verify-register','BD-verify-result','BD-verify-api'],derivation='S-client states that VerifyLeader ensures the peer is still leader and may prevent stale FSM reads after leadership loss. This obligation asks only for rejection of an independently established obsolete authority, not freshness of a current leader FSM. S-config and S-membership-api distinguish voter from nonvoter participation. The implementation contrast is voter-count quorumSize versus all-replicator registration; S-loop consumes the tally without a second voter qualification. S-lease independently ends local authority but is timer-scheduled, not a prerequisite of VerifyLeader success. S-timer-contract describes server-local timers; S-config-validation enforces each local lease <= heartbeat <= election setting, with no requirement that values match across peers.',applicability='The check must witness the higher term and completed command before invocation and keep the partition in place until the result. A valid local timer configuration alone is not proof that the desired history was reached.',unresolved=[],conflicts=[],alternatives=['The old peer may process its voter-only lease check or a negative reply before completion and correctly return an error.','Old in-flight voter replies could explain a result unless their lifecycle is accounted for; this must remain visible in the harness and correspondence review.']))
def bind(id,mat,sym,a,b,desc):
 return dict(id=id,material_id=mat,symbol=sym,start_line=a,end_line=b,description=desc,pending=[],associations=[dict(claim_id=claim['id'],source_ids=[mat,'S-client'],rationale=desc)])
bindings=[bind('BD-verify-register','S-verify','verifyLeader',965,988,'Initializes voter-based threshold but registers all replication peers for the authority check.'),bind('BD-verify-result','S-loop','leaderLoop',844,868,'Consumes the verification tally and exposes nil completion when it reaches quorumSize.'),bind('BD-verify-api','S-client','VerifyLeader',880,895,'Public authority-check contract and invocation path returning the verification future.')]
